blobs.0f9b3a2a5cd9:
// The ARRANGEMENT — the timeline, and the transport that rolls through it.
//
// A project draws one because it says so here: the timeline is a SURFACE
// (packages/song/docs/surfaces.md), not something the editor hands out for free. Take this
// file away and the song still compiles and still plays — you simply have no lanes on screen.
//
// `split` is what puts it in the layout, sharing the window with the graph underneath, and is
// the only layout a timeline draws in. `view` is the other one: a screen of its own off the
// header, which is where a turntables desk goes.
type("timeline")
layout("split")

blobs.52272c02f534:
// The shader the main lane runs through. Its `audio` port is a SIDE input: the drums lane feeds it
// as well as the mix, and `uAudio` is that lane's live level, so the picture moves with the kit.
ports(["audio"])
steps([
  id("$UUID6").extends("@workspace/shaders/glow"),
  to([chain("RENDER")]),
])

blobs.5db7ce4a37d3:
// The FRAME — this song's three video lanes composited with WebGL, drawn against the
// engine's playhead.
//
// `floating` is the only layout it draws in: a window over whichever page is on screen,
// moved by its title bar and sized by its corner. `ui viewport` shows or hides it; hidden,
// it keeps its GL context and its <video> per layer, so showing it again costs nothing.
//
// Take this file away and the lanes still compile and still draw on the timeline — nothing
// composites them, and `surfaceIssues` says so. See packages/song/docs/surfaces.md.
type("viewport")
layout("floating")

blobs.7b1d7e4195f7:
// A video clip (kind read from the .mp4 extension). testsrc burns the frame number
// into the picture, so sync and a shot's `from` are checkable by eye.

source("clips/counter.mp4")

blobs.84a5543c7124:
// The lane the "title" shape module draws on — one shape per layer, so each can be hidden on its
// own and take its own run of effects. No rect: a shape carries its own geometry, so this layer
// covers the whole viewport.
//
// The events name no clip, and that is what they are for here: each is an ACTIVATION, saying WHEN
// the shape is on screen. A lane stating none draws its shapes throughout.
extends("@meta/picture-track")
events([start(4).length(4)])

blobs.857ffb0f0fd0:
// The lane the "box" shape module draws on — one shape per layer, so each can be hidden on its
// own and take its own run of effects. No rect: a shape carries its own geometry, so this layer
// covers the whole viewport.
//
// The events name no clip, and that is what they are for here: each is an ACTIVATION, saying WHEN
// the shape is on screen. A lane stating none draws its shapes throughout.
extends("@meta/picture-track")
events([start(0).length(4)])

blobs.93be9e96fa8f:
// A SHAPE is a picture source: it starts the chain of the lane it draws on, as a camera would.
// See packages/song-video/docs/shapes.md.
start(true)
steps([
  id("$UUID1").extends("@workspace/shapes/box"),
  id("$UUID2").track("box_layer"),
])

blobs.99b93fd0ffc3:
// A LIVE rig: something plugged in, heard through this machine.
//
// It declares no `surfaces/` — no timeline, no viewport, no desk — and that is the whole
// of what makes it this shape rather than another. A project draws what it DECLARES, so
// this one opens on its graph and nothing else. See packages/song/docs/liveProject.md.
//
// It holds no material either: no `clips/`, no `sequences/`. Nothing is arranged, so
// nothing warns about an arrangement that is not drawn.
project({
  name: "live",
  // Kept although nothing is arranged: the metronome counts in it, and so does a
  // delay whose time is written in beats.
  tempo: 120,
  sampleRate: 48000,
})

blobs.a07aa56a5653:
// The PICTURE's run: RENDER is where the lanes composite and VIDEO_OUT is the frame that leaves.
// Neither carries a param — a frame has no level. See packages/song/docs/videoOutputs.md.
start("RENDER")
steps([to([chain("VIDEO_OUT")])])

blobs.a248b10f6022:
// An AUDIO clip living in the same clips/ folder — proves the two kinds coexist and
// are told apart by extension.

source("clips/kick.wav")

blobs.a456b85e8cac:
// A SHAPE is a picture source: it starts the chain of the lane it draws on, as a camera would.
// See packages/song-video/docs/shapes.md.
start(true)
steps([
  id("$UUID3").extends("@workspace/shapes/dot"),
  id("$UUID4").track("dot_layer"),
])

blobs.bff5ff89181e:
// The lane the "dot" shape module draws on — one shape per layer, so each can be hidden on its
// own and take its own run of effects. No rect: a shape carries its own geometry, so this layer
// covers the whole viewport.
//
// The events name no clip, and that is what they are for here: each is an ACTIVATION, saying WHEN
// the shape is on screen. A lane stating none draws its shapes throughout.
extends("@meta/picture-track")
events([start(2).length(4)])

blobs.d7bc3e22353b:
// The picture lane `main`: its lane item heads its chain, and its shots live in tracks/main,
// a `@meta/picture-track` lane. Its run goes through the `glow` shader on its way to RENDER.
//
// `iris` is a SUBCHAIN that nothing links and that links nowhere: a fade's STRETCH. The second shot
// on main names it (`fadeIn({ over: 1, chain: "iris" })`) and runs through it on its way in.
// See packages/song-video/docs/transitions.md and packages/song/docs/chainFiles.md.
start(true)
steps([id("$UUID7").track("main"), to([chain("glow")])])
subchains([
  id("iris").steps([id("$UUID8").extends("@workspace/shaders/iris")]),
])

blobs.dcd9053348ef:
// The metronome is OFF: a rig you play through is not a rig you record to a click.
metronome(false)
count_in(1)

blobs.eabaaa55ad9a:
// The drums lane: into the mix, and into `glow`'s audio port — see glow.k7x.
start(true)
steps([
  id("$UUID5").track("drums"),
  to([chain("MIX").level(1), chain("glow").port("audio").level(1)]),
])

